//! JSON Schema export for the public wire types.
//! Spec: `docs/design/types.md` §14 and `docs/design/crates/vowp-protocol.md` §4 rule 12.
//!
//! [`all_schemas`] is keyed by Rust type name and sorted, so `vowp schema` output is stable.
//! Every value is a JSON Schema document generated by `schemars` from the same definition the
//! wire format uses.

use std::collections::BTreeMap;

use schemars::JsonSchema;

use crate::capsule::{Capsule, CapsuleDraft};
use crate::config::VowpConfig;
use crate::cost::Cost;
use crate::event::EventEnvelope;
use crate::executor::Profile;
use crate::gate::{Evidence, Gate, GateResult};
use crate::inbox::InboxItem;
use crate::job::{Edge, Job, JobPatch, NewJob};
use crate::limit::Limit;
use crate::loops::{Loop, Schedule};
use crate::release::Release;
use crate::report::{BriefFrontMatter, ReportFrontMatter};
use crate::run::{Run, Worker};
use crate::session::{LedgerEntry, Node, Project, Session, Switch};

/// Renders the schema for `T` as a JSON value.
fn schema_value<T: JsonSchema>() -> serde_json::Value {
    // invariant: schemars schemas contain only JSON-serialisable values.
    serde_json::to_value(schemars::schema_for!(T)).expect("invariant: schema serialises to JSON")
}

/// Returns every exported JSON Schema, keyed by Rust type name.
pub fn all_schemas() -> BTreeMap<&'static str, serde_json::Value> {
    let mut schemas = BTreeMap::new();
    schemas.insert("EventEnvelope", schema_value::<EventEnvelope>());
    schemas.insert("Capsule", schema_value::<Capsule>());
    schemas.insert("CapsuleDraft", schema_value::<CapsuleDraft>());
    schemas.insert("Job", schema_value::<Job>());
    schemas.insert("NewJob", schema_value::<NewJob>());
    schemas.insert("JobPatch", schema_value::<JobPatch>());
    schemas.insert("Gate", schema_value::<Gate>());
    schemas.insert("Evidence", schema_value::<Evidence>());
    schemas.insert("GateResult", schema_value::<GateResult>());
    schemas.insert("ReportFrontMatter", schema_value::<ReportFrontMatter>());
    schemas.insert("BriefFrontMatter", schema_value::<BriefFrontMatter>());
    schemas.insert("VowpConfig", schema_value::<VowpConfig>());
    schemas.insert("Schedule", schema_value::<Schedule>());
    schemas.insert("Release", schema_value::<Release>());
    schemas.insert("InboxItem", schema_value::<InboxItem>());
    schemas.insert("Run", schema_value::<Run>());
    schemas.insert("Worker", schema_value::<Worker>());
    schemas.insert("Session", schema_value::<Session>());
    schemas.insert("Limit", schema_value::<Limit>());
    schemas.insert("Cost", schema_value::<Cost>());
    schemas.insert("Switch", schema_value::<Switch>());
    schemas.insert("Loop", schema_value::<Loop>());
    schemas.insert("Node", schema_value::<Node>());
    schemas.insert("Project", schema_value::<Project>());
    schemas.insert("Profile", schema_value::<Profile>());
    schemas.insert("Edge", schema_value::<Edge>());
    schemas.insert("LedgerEntry", schema_value::<LedgerEntry>());
    schemas
}

/// Returns the schema for one type name, or `None` when it is not exported.
pub fn schema_for_name(name: &str) -> Option<serde_json::Value> {
    all_schemas().remove(name)
}
